function [ape] = pointing_error_rss(terms)
%POINTING_ERROR_RSS  The root sum square of the five pointing-error terms (knowledge, control, alignment,
%   thermal, jitter). (base)
%   terms: real[rad][5] (passed a plain number)
%   returns ape: real[rad] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ape = 0;
    h__10 = asils.pc.dot_(terms, terms);
    if h__10 < 0, h__10 = NaN; else, h__10 = sqrt(h__10); end
    ape = h__10;
end
